cssCode:
.battery-body {
  width: 80px; height: 150px; border: 4px solid #fff; border-radius: 10px;
  position: relative; overflow: hidden; background: #222;
  box-shadow: 0 0 15px rgba(255,255,255,0.2);
}
.battery-body::before {
  content: ''; position: absolute; top: -12px; left: 50%; transform: translateX(-50%);
  width: 30px; height: 8px; background: #fff; border-radius: 4px 4px 0 0;
}
.fluid-fill {
  position: absolute; bottom: -20px; left: -50%; width: 200%; height: 200%;
  background: linear-gradient(0deg, #00ffcc, #00b3ff);
  border-radius: 40%; animation: fluidSpin 4s linear infinite, chargeUp 6s ease-in-out infinite alternate;
  box-shadow: 0 0 20px #00ffcc;
}
@keyframes fluidSpin { 100% { transform: rotate(360deg); } }
@keyframes chargeUp { 0% { bottom: -180%; } 100% { bottom: -20%; } }

